def retry_call(fn, attempts, sleep):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    last_exc = None
    for i in range(attempts):
        try:
            return fn()
        except Exception as exc:
            last_exc = exc
            if i < attempts - 1:
                sleep(1)
    raise last_exc
```

